=== FILE: rtl/axil_timer.v ===
// axil_timer: AXI4-Lite timer peripheral with a level interrupt.
// Implements microarchitecture_spec.md (prj-ada3a9b9d9.microarchitecture.a2),
// derived from interface_spec.md (prj-ada3a9b9d9.interface-spec.a2).
// Traces to req-2b2b91a584. TMR-LOAD-END-EDGE resolved as "reload old LOAD".
`default_nettype none

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // ---------------------------------------------------------------- state
  reg                  aw_held_q;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held_q;
  reg [31:0]           wdata_q;
  reg [3:0]            wstrb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [31:0]           rdata_q;
  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;
  reg                  expired_q;
  reg                  irq_q;

  // ----------------------------------------------------------- write path
  wire aw_ready = ~aw_held_q & ~bvalid_q;
  wire w_ready  = ~w_held_q  & ~bvalid_q;
  wire aw_fire  = s_axil_awvalid & aw_ready;
  wire w_fire   = s_axil_wvalid  & w_ready;
  wire wr_go    = (aw_fire & (w_fire | w_held_q)) | (w_fire & aw_held_q);

  wire [ADDR_WIDTH-1:0] wa = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wd = w_held_q  ? wdata_q   : s_axil_wdata;
  wire [3:0]            ws = w_held_q  ? wstrb_q   : s_axil_wstrb;

  // ------------------------------------------------------------ read path
  wire ar_ready = ~rvalid_q;
  wire ar_fire  = s_axil_arvalid & ar_ready;

  // --------------------------------------------------------------- decode
  wire wa_hi_zero;
  wire ra_hi_zero;
  generate
    if (ADDR_WIDTH > 4) begin : g_hi
      assign wa_hi_zero = ~|wa[ADDR_WIDTH-1:4];
      assign ra_hi_zero = ~|s_axil_araddr[ADDR_WIDTH-1:4];
    end else begin : g_no_hi
      assign wa_hi_zero = 1'b1;
      assign ra_hi_zero = 1'b1;
    end
  endgenerate

  wire [1:0] wa_idx    = wa[3:2];
  wire       wa_mapped = (wa[1:0] == 2'b00) & wa_hi_zero;
  wire       wr_ok     = wa_mapped & (wa_idx != IDX_COUNT);

  wire [1:0] ra_idx    = s_axil_araddr[3:2];
  wire       rd_ok     = (s_axil_araddr[1:0] == 2'b00) & ra_hi_zero;

  reg [31:0] rd_val;
  always @(*) begin
    rd_val = 32'd0;
    case (ra_idx)
      IDX_CTRL:   rd_val = {29'd0, mode_q, ie_q, en_q};
      IDX_LOAD:   rd_val = load_q;
      IDX_COUNT:  rd_val = count_q;
      IDX_STATUS: rd_val = {31'd0, expired_q};
      default:    rd_val = 32'd0;
    endcase
  end

  // ------------------------------------------------- register write enables
  wire       wr_sel     = wr_go & wr_ok;
  wire       ctrl_we    = wr_sel & (wa_idx == IDX_CTRL) & ws[0];
  wire [3:0] load_be    = {4{wr_sel & (wa_idx == IDX_LOAD)}} & ws;
  wire       status_clr = wr_sel & (wa_idx == IDX_STATUS) & ws[0] & wd[0];
  wire       restart    = ctrl_we & wd[0];
  wire       stop       = ctrl_we & ~wd[0];

  // ------------------------------------------------------------ timer core
  wire end_edge = en_q & (count_q[31:1] == 31'd0);

  reg [31:0] count_d;
  reg        en_d;
  always @(*) begin
    count_d = count_q;
    en_d    = en_q;
    if (restart) begin
      count_d = load_q;
      en_d    = 1'b1;
    end else if (end_edge && !mode_q) begin
      count_d = 32'd0;
      en_d    = 1'b0;
    end else if (end_edge) begin
      count_d = load_q;          // TMR-LOAD-END-EDGE: old LOAD
      en_d    = ~stop;
    end else if (en_q) begin
      count_d = count_q - 32'd1;
      en_d    = ~stop;
    end else begin
      count_d = count_q;
      en_d    = 1'b0;
    end
  end

  wire        ie_d      = ctrl_we ? wd[1] : ie_q;
  wire        mode_d    = ctrl_we ? wd[2] : mode_q;
  wire        expired_d = end_edge ? 1'b1 : (status_clr ? 1'b0 : expired_q);
  wire [31:0] load_d    = {load_be[3] ? wd[31:24] : load_q[31:24],
                           load_be[2] ? wd[23:16] : load_q[23:16],
                           load_be[1] ? wd[15:8]  : load_q[15:8],
                           load_be[0] ? wd[7:0]   : load_q[7:0]};

  // ------------------------------------------------------------- flops
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_held_q  <= 1'b0;
      wdata_q   <= 32'd0;
      wstrb_q   <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= 2'b00;
      rvalid_q  <= 1'b0;
      rresp_q   <= 2'b00;
      rdata_q   <= 32'd0;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
      expired_q <= 1'b0;
      irq_q     <= 1'b0;
    end else begin
      if (wr_go) begin
        aw_held_q <= 1'b0;
        w_held_q  <= 1'b0;
        bvalid_q  <= 1'b1;
        bresp_q   <= wr_ok ? RESP_OKAY : RESP_SLVERR;
      end else begin
        if (aw_fire) begin
          aw_held_q <= 1'b1;
          aw_addr_q <= s_axil_awaddr;
        end
        if (w_fire) begin
          w_held_q <= 1'b1;
          wdata_q  <= s_axil_wdata;
          wstrb_q  <= s_axil_wstrb;
        end
        if (bvalid_q & s_axil_bready) begin
          bvalid_q <= 1'b0;
        end
      end

      if (ar_fire) begin
        rvalid_q <= 1'b1;
        rresp_q  <= rd_ok ? RESP_OKAY : RESP_SLVERR;
        rdata_q  <= rd_ok ? rd_val : 32'd0;
      end else if (rvalid_q & s_axil_rready) begin
        rvalid_q <= 1'b0;
      end

      en_q      <= en_d;
      ie_q      <= ie_d;
      mode_q    <= mode_d;
      load_q    <= load_d;
      count_q   <= count_d;
      expired_q <= expired_d;
      irq_q     <= expired_d & ie_d;
    end
  end

  // ------------------------------------------------------------- outputs
  assign s_axil_awready = aw_ready;
  assign s_axil_wready  = w_ready;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = ar_ready;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;
  assign irq            = irq_q;

  // ------------------------------------------- design-intent assertions
`ifdef FORMAL
  always @(posedge aclk) begin
    if (aresetn) begin
      assert (!(aw_held_q && w_held_q));                      // W-EXCL
      assert (!bvalid_q || (!aw_held_q && !w_held_q));         // W-QUIET
      assert (irq_q == (expired_q & ie_q));                    // TMR-IRQ
      assert (bresp_q[0] == 1'b0);                             // OKAY/SLVERR only
      assert (rresp_q[0] == 1'b0);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: tb/axil_timer_tb.v ===
// Self-checking testbench for axil_timer (prj-ada3a9b9d9:rtl-implementation).
// Checks interface_spec.md rules timed to the edge at ADDR_WIDTH 4, 5 and 8.
`timescale 1ns/1ps

module axil_timer_tb_core;
  parameter integer AW = 4;

  localparam [31:0] A_CTRL   = 32'h0;
  localparam [31:0] A_LOAD   = 32'h4;
  localparam [31:0] A_COUNT  = 32'h8;
  localparam [31:0] A_STATUS = 32'hC;
  localparam [1:0]  OK  = 2'b00;
  localparam [1:0]  SLV = 2'b10;
  localparam [31:0] EN   = 32'h1;
  localparam [31:0] IE   = 32'h2;
  localparam [31:0] MODE = 32'h4;

  reg aclk = 1'b0;
  always #5 aclk = ~aclk;

  reg          aresetn;
  reg [AW-1:0] awaddr;
  reg          awvalid;
  wire         awready;
  reg [31:0]   wdata;
  reg [3:0]    wstrb;
  reg          wvalid;
  wire         wready;
  wire [1:0]   bresp;
  wire         bvalid;
  reg          bready;
  reg [AW-1:0] araddr;
  reg          arvalid;
  wire         arready;
  wire [31:0]  rdata;
  wire [1:0]   rresp;
  wire         rvalid;
  reg          rready;
  wire         irq;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
    .irq(irq)
  );

  integer passed;
  integer failed;
  integer cyc;
  integer wr_edge;
  integer e0, e1, x, t, v, k;
  reg     done;
  reg [31:0] rd_last;
  reg [1:0]  rresp_last;
  reg [31:0] snap;

  // ------------------------------------------------------------ helpers
  task step;
    begin
      @(posedge aclk);
      #1;
      cyc = cyc + 1;
    end
  endtask

  task wait_until;
    input integer target;
    begin
      while (cyc < target) step;
    end
  endtask

  task check;
    input cond;
    input [8*64-1:0] msg;
    begin
      if (cond === 1'b1) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("AW=%0d cyc=%0d: %0s", AW, cyc, msg);
      end
    end
  endtask

  task check_eq;
    input [31:0] got;
    input [31:0] expv;
    input [8*64-1:0] msg;
    begin
      if (got === expv) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("AW=%0d cyc=%0d: %0s: got 0x%08h expected 0x%08h", AW, cyc, msg, got, expv);
      end
    end
  endtask

  // Offer AW and W together; returns right after the completing edge.
  task wr_nb;
    input [31:0] addr;
    input [31:0] data;
    input [3:0]  strb;
    input [1:0]  exp_resp;
    begin
      bready = 1'b1;
      while (bvalid === 1'b1) step;
      check(awready === 1'b1 && wready === 1'b1, "awready/wready high when idle");
      awaddr  = addr[AW-1:0];
      wdata   = data;
      wstrb   = strb;
      awvalid = 1'b1;
      wvalid  = 1'b1;
      step;
      wr_edge = cyc;
      awvalid = 1'b0;
      wvalid  = 1'b0;
      check(bvalid === 1'b1, "bvalid high after completing edge");
      check_eq({30'd0, bresp}, {30'd0, exp_resp}, "bresp");
      check(awready === 1'b0 && wready === 1'b0, "awready/wready low while bvalid");
    end
  endtask

  task wr;
    input [31:0] addr;
    input [31:0] data;
    input [3:0]  strb;
    input [1:0]  exp_resp;
    begin
      wr_nb(addr, data, strb, exp_resp);
      step;
      check(bvalid === 1'b0, "bvalid low after edge with bready");
    end
  endtask

  // Write that completes exactly on edge 'target'.
  task wr_at;
    input integer target;
    input [31:0] addr;
    input [31:0] data;
    input [3:0]  strb;
    input [1:0]  exp_resp;
    begin
      bready = 1'b1;
      while (bvalid === 1'b1) step;
      if (cyc > target - 1) begin
        failed = failed + 1;
        $error("AW=%0d cyc=%0d: TB cannot reach edge %0d", AW, cyc, target);
      end
      wait_until(target - 1);
      wr_nb(addr, data, strb, exp_resp);
      check(wr_edge == target, "write completed on intended edge");
    end
  endtask

  // Read: captures the value present in the cycle of the call.
  task rd_raw;
    input [31:0] addr;
    begin
      rready = 1'b1;
      while (rvalid === 1'b1) step;
      check(arready === 1'b1, "arready high when idle");
      araddr  = addr[AW-1:0];
      arvalid = 1'b1;
      step;
      arvalid = 1'b0;
      check(rvalid === 1'b1, "rvalid high after accepting edge");
      check(arready === 1'b0, "arready low while rvalid");
      rd_last    = rdata;
      rresp_last = rresp;
      step;
      check(rvalid === 1'b0, "rvalid low after edge with rready");
    end
  endtask

  task rd;
    input [31:0] addr;
    input [31:0] expd;
    input [1:0]  exp_resp;
    input [8*64-1:0] msg;
    begin
      rd_raw(addr);
      check_eq(rd_last, expd, msg);
      check_eq({30'd0, rresp_last}, {30'd0, exp_resp}, "rresp");
    end
  endtask

  task clear_status;
    begin
      wr(A_STATUS, 32'h1, 4'hF, OK);
    end
  endtask

  task unmapped;
    input [31:0] a;
    begin
      wr(a, 32'hFFFF_FFFF, 4'hF, SLV);
      rd(a, 32'h0, SLV, "unmapped read returns 0");
    end
  endtask

  // ------------------------------------------------------------ tests
  initial begin
    passed = 0; failed = 0; cyc = 0; done = 1'b0; wr_edge = 0;
    aresetn = 1'b0;
    awaddr = {AW{1'b0}}; awvalid = 1'b0;
    wdata = 32'd0; wstrb = 4'd0; wvalid = 1'b0; bready = 1'b0;
    araddr = {AW{1'b0}}; arvalid = 1'b0; rready = 1'b0;
    step; step;
    aresetn = 1'b1;

    // T1: reset values
    check(bvalid === 1'b0 && rvalid === 1'b0, "no responses after reset");
    check(irq === 1'b0, "irq 0 after reset");
    check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "READYs after reset");
    rd(A_CTRL,   32'h0, OK, "CTRL reset");
    rd(A_LOAD,   32'h0, OK, "LOAD reset");
    rd(A_COUNT,  32'h0, OK, "COUNT reset");
    rd(A_STATUS, 32'h0, OK, "STATUS reset");

    // T2: register access rules
    wr(A_LOAD, 32'hA5A5_1234, 4'hF, OK);
    rd(A_LOAD, 32'hA5A5_1234, OK, "LOAD full write");
    wr(A_LOAD, 32'hFFFF_FFFF, 4'b0101, OK);
    rd(A_LOAD, 32'hA5FF_12FF, OK, "LOAD strobes 0101");
    wr(A_LOAD, 32'h0, 4'b0000, OK);
    rd(A_LOAD, 32'hA5FF_12FF, OK, "LOAD strobes 0000");
    wr(A_LOAD, 32'h0, 4'b1010, OK);
    rd(A_LOAD, 32'h00FF_00FF, OK, "LOAD strobes 1010");
    wr(A_CTRL, 32'hFFFF_FFFA, 4'b1110, OK);
    rd(A_CTRL, 32'h0, OK, "CTRL needs wstrb[0]");
    wr(A_CTRL, 32'hFFFF_FFFA, 4'b0001, OK);
    rd(A_CTRL, IE, OK, "CTRL bits 31:3 read 0");
    check(irq === 1'b0, "irq 0 with IE 1 and EXPIRED 0");
    wr(A_CTRL, 32'h0, 4'hF, OK);
    rd(A_CTRL, 32'h0, OK, "CTRL cleared");
    wr(A_COUNT, 32'h1234, 4'hF, SLV);
    rd(A_COUNT, 32'h0, OK, "COUNT write ignored");
    wr(A_STATUS, 32'h0, 4'hF, OK);
    rd(A_STATUS, 32'h0, OK, "STATUS write 0");
    wr(A_STATUS, 32'h1, 4'hF, OK);
    rd(A_STATUS, 32'h0, OK, "STATUS clear when 0");
    unmapped(32'h1); unmapped(32'h2); unmapped(32'h3);
    unmapped(32'h5); unmapped(32'h6); unmapped(32'h7);
    unmapped(32'h9); unmapped(32'hD); unmapped(32'hE); unmapped(32'hF);
    if (AW > 4) begin
      unmapped(32'h10); unmapped(32'h14); unmapped(32'h18); unmapped(32'h1C);
      unmapped((32'h1 << AW) - 32'd4);
      unmapped((32'h1 << AW) - 32'd1);
      unmapped(32'h1 << (AW - 1));
    end
    rd(A_LOAD,   32'h00FF_00FF, OK, "LOAD unchanged by unmapped");
    rd(A_CTRL,   32'h0, OK, "CTRL unchanged by unmapped");
    rd(A_COUNT,  32'h0, OK, "COUNT unchanged by unmapped");
    rd(A_STATUS, 32'h0, OK, "STATUS unchanged by unmapped");

    // T3: write ordering and B channel
    bready = 1'b1;
    awaddr = A_LOAD; awvalid = 1'b1; wvalid = 1'b0;
    step; awvalid = 1'b0;
    check(awready === 1'b0 && wready === 1'b1, "AW held: awready 0, wready 1");
    check(bvalid === 1'b0, "no bvalid with only AW");
    step; step;
    check(bvalid === 1'b0 && awready === 1'b0, "held AW waits");
    wdata = 32'h1111_2222; wstrb = 4'hF; wvalid = 1'b1;
    step; wvalid = 1'b0;
    check(bvalid === 1'b1, "AW then W: bvalid after W edge");
    check_eq({30'd0, bresp}, {30'd0, OK}, "AW then W bresp");
    check(awready === 1'b0 && wready === 1'b0, "READYs low while bvalid");
    step;
    check(bvalid === 1'b0 && awready === 1'b1 && wready === 1'b1, "B taken, idle");
    rd(A_LOAD, 32'h1111_2222, OK, "AW then W data");

    wdata = 32'h3333_4444; wstrb = 4'hF; wvalid = 1'b1;
    step; wvalid = 1'b0;
    check(wready === 1'b0 && awready === 1'b1, "W held: wready 0, awready 1");
    check(bvalid === 1'b0, "no bvalid with only W");
    step;
    check(bvalid === 1'b0, "held W waits");
    awaddr = A_LOAD; awvalid = 1'b1;
    step; awvalid = 1'b0;
    check(bvalid === 1'b1, "W then AW: bvalid after AW edge");
    check_eq({30'd0, bresp}, {30'd0, OK}, "W then AW bresp");
    step;
    check(bvalid === 1'b0, "B taken");
    rd(A_LOAD, 32'h3333_4444, OK, "W then AW data");

    wdata = 32'hDEAD; wstrb = 4'hF; wvalid = 1'b1;
    step; wvalid = 1'b0;
    awaddr = A_COUNT; awvalid = 1'b1;
    step; awvalid = 1'b0;
    check(bvalid === 1'b1, "W then AW to COUNT: bvalid");
    check_eq({30'd0, bresp}, {30'd0, SLV}, "W then AW to COUNT SLVERR");
    step;
    rd(A_LOAD, 32'h3333_4444, OK, "LOAD unchanged by COUNT write");

    // B stall with a second write offered
    bready = 1'b0;
    awaddr = A_LOAD; wdata = 32'h5555; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
    step;
    wdata = 32'h6666;
    check(bvalid === 1'b1, "stall: bvalid");
    check(awready === 1'b0 && wready === 1'b0, "stall: READYs low");
    for (k = 0; k < 3; k = k + 1) begin
      step;
      check(bvalid === 1'b1, "stall: bvalid held");
      check_eq({30'd0, bresp}, {30'd0, OK}, "stall: bresp stable");
      check(awready === 1'b0 && wready === 1'b0, "stall: READYs held low");
    end
    rd(A_LOAD, 32'h5555, OK, "second write not accepted under stall");
    bready = 1'b1;
    step;
    check(bvalid === 1'b0, "stall released");
    check(awready === 1'b1 && wready === 1'b1, "READYs back after B");
    step;
    awvalid = 1'b0; wvalid = 1'b0;
    check(bvalid === 1'b1, "offered write completes after stall");
    step;
    check(bvalid === 1'b0, "second B taken");
    rd(A_LOAD, 32'h6666, OK, "second write data");

    // SLVERR stable under stall
    bready = 1'b0;
    awaddr = A_COUNT; wdata = 32'h1; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
    step; awvalid = 1'b0; wvalid = 1'b0;
    for (k = 0; k < 3; k = k + 1) begin
      check(bvalid === 1'b1, "SLVERR stall: bvalid held");
      check_eq({30'd0, bresp}, {30'd0, SLV}, "SLVERR stall: bresp stable");
      step;
    end
    bready = 1'b1;
    step;
    check(bvalid === 1'b0, "SLVERR stall released");

    // T4: read stall, snapshot stability
    wr(A_LOAD, 32'd100, 4'hF, OK);
    wr_nb(A_CTRL, EN, 4'hF, OK);
    e0 = wr_edge;
    rready = 1'b0;
    araddr = A_COUNT; arvalid = 1'b1;
    x = cyc;
    step;
    araddr = A_CTRL;
    check(rvalid === 1'b1, "R stall: rvalid");
    snap = rdata;
    check_eq(snap, 32'd100 - (x - e0), "R stall: COUNT snapshot");
    for (k = 0; k < 3; k = k + 1) begin
      step;
      check(rvalid === 1'b1, "R stall: rvalid held");
      check_eq(rdata, snap, "R stall: rdata stable while COUNT moves");
      check_eq({30'd0, rresp}, {30'd0, OK}, "R stall: rresp stable");
      check(arready === 1'b0, "R stall: arready low");
    end
    rready = 1'b1;
    step;
    check(rvalid === 1'b0 && arready === 1'b1, "R stall released");
    step;
    arvalid = 1'b0;
    check(rvalid === 1'b1, "offered read accepted after stall");
    check_eq(rdata, EN, "offered CTRL read");
    step;
    check(rvalid === 1'b0, "R taken");
    wr(A_CTRL, 32'h0, 4'hF, OK);
    rready = 1'b0;
    araddr = 5; arvalid = 1'b1;
    step; arvalid = 1'b0;
    for (k = 0; k < 3; k = k + 1) begin
      check(rvalid === 1'b1, "SLVERR R stall: rvalid");
      check_eq({30'd0, rresp}, {30'd0, SLV}, "SLVERR R stall: rresp");
      check_eq(rdata, 32'h0, "SLVERR R stall: rdata 0");
      step;
    end
    rready = 1'b1;
    step;
    check(rvalid === 1'b0, "SLVERR R taken");

    // T5: read and write on the same edge
    rd(A_LOAD, 32'd100, OK, "LOAD before cross test");
    araddr = A_LOAD; arvalid = 1'b1; rready = 1'b1;
    awaddr = A_LOAD; wdata = 32'hABCD; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1; bready = 1'b1;
    step;
    arvalid = 1'b0; awvalid = 1'b0; wvalid = 1'b0;
    check(rvalid === 1'b1 && bvalid === 1'b1, "cross: both responses");
    check_eq(rdata, 32'd100, "cross: read sees value before edge");
    step;
    check(rvalid === 1'b0 && bvalid === 1'b0, "cross: both taken");
    rd(A_LOAD, 32'hABCD, OK, "cross: write took effect");

    // T6: one-shot irq timing, LOAD 5
    clear_status;
    wr(A_LOAD, 32'd5, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    e0 = wr_edge;
    for (k = 0; k < 5; k = k + 1) begin
      check(irq === 1'b0, "one-shot: irq low before end");
      step;
    end
    check(cyc == e0 + 5, "TB timing");
    check(irq === 1'b1, "one-shot: irq high after E+N");
    rd(A_CTRL, IE, OK, "one-shot: EN cleared at end");
    rd(A_COUNT, 32'h0, OK, "one-shot: COUNT 0 at end");
    rd(A_STATUS, 32'h1, OK, "one-shot: EXPIRED");
    repeat (5) step;
    check(irq === 1'b1, "irq level held");
    rd(A_COUNT, 32'h0, OK, "one-shot: stays 0");
    wr(A_STATUS, 32'h0, 4'hF, OK);
    rd(A_STATUS, 32'h1, OK, "STATUS write 0 keeps EXPIRED");
    wr(A_STATUS, 32'h1, 4'b1110, OK);
    rd(A_STATUS, 32'h1, OK, "STATUS clear needs wstrb[0]");
    wr(A_STATUS, 32'h2, 4'hF, OK);
    rd(A_STATUS, 32'h1, OK, "STATUS bit1 write keeps EXPIRED");
    wr_nb(A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b0, "irq low after clear edge");
    step;
    rd(A_STATUS, 32'h0, OK, "EXPIRED cleared");

    // T7: COUNT read at every k, LOAD 7
    wr(A_LOAD, 32'd7, 4'hF, OK);
    wr_nb(A_CTRL, EN, 4'hF, OK);
    e0 = wr_edge;
    while (cyc - e0 < 7) rd(A_COUNT, 32'd7 - (cyc - e0), OK, "COUNT = N-k (even k)");
    rd(A_COUNT, 32'h0, OK, "COUNT 0 after end");
    rd(A_STATUS, 32'h1, OK, "EXPIRED after LOAD 7");
    clear_status;
    wr(A_CTRL, EN, 4'hF, OK);
    e0 = wr_edge;
    while (cyc - e0 < 7) rd(A_COUNT, 32'd7 - (cyc - e0), OK, "COUNT = N-k (odd k)");
    check(cyc == e0 + 7, "TB timing odd");
    rd(A_COUNT, 32'h0, OK, "COUNT 0 after E+N");
    rd(A_STATUS, 32'h1, OK, "EXPIRED after second LOAD 7");
    clear_status;

    // T8: periodic LOAD 3
    wr(A_LOAD, 32'd3, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE | MODE, 4'hF, OK);
    e0 = wr_edge;
    while (cyc - e0 < 12) rd(A_COUNT, 32'd3 - ((cyc - e0) % 3), OK, "periodic COUNT");
    check(irq === 1'b1, "periodic: irq");
    rd(A_CTRL, EN | IE | MODE, OK, "periodic: EN stays 1");
    t = cyc + 1;
    while (((t - e0) % 3) != 0) t = t + 1;
    wr_at(t, A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b1, "END-BEATS-CLEAR: irq stays");
    rd(A_STATUS, 32'h1, OK, "END-BEATS-CLEAR: EXPIRED");
    t = cyc + 1;
    while (((t - e0) % 3) != 1) t = t + 1;
    wr_at(t, A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b0, "clear off end edge: irq low");
    step;
    check(irq === 1'b0, "irq low until next end");
    step;
    check(irq === 1'b1, "periodic end re-sets EXPIRED");
    step; step;
    t = cyc + 1;
    while (((t - e0) % 3) != 1) t = t + 1;
    wr_at(t, A_CTRL, IE | MODE, 4'hF, OK);
    rd(A_COUNT, 32'd2, OK, "stop edge decrements");
    repeat (5) step;
    rd(A_COUNT, 32'd2, OK, "stopped COUNT holds");
    rd(A_CTRL, IE | MODE, OK, "stopped CTRL");
    clear_status;
    repeat (6) step;
    rd(A_STATUS, 32'h0, OK, "no ends after stop");
    check(irq === 1'b0, "irq low after stop and clear");
    wr(A_CTRL, IE | MODE, 4'hF, OK);
    rd(A_COUNT, 32'd2, OK, "EN 0 while EN 0 keeps COUNT");

    // T9: CTRL write on end edge
    // (a) one-shot, EN 1 -> restart
    clear_status;
    wr(A_LOAD, 32'd4, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 4, A_CTRL, EN | IE, 4'hF, OK);
    e1 = wr_edge;
    check(irq === 1'b1, "CTRL-WINS EN1: EXPIRED set");
    rd(A_COUNT, 32'd4, OK, "CTRL-WINS EN1: COUNT = LOAD");
    wr_at(e1 + 3, A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b0, "CTRL-WINS EN1: cleared");
    step;
    check(irq === 1'b1, "CTRL-WINS EN1: restarted count ends");
    rd(A_CTRL, IE, OK, "CTRL-WINS EN1: one-shot ended");
    rd(A_COUNT, 32'h0, OK, "CTRL-WINS EN1: COUNT 0");
    // (b) one-shot, EN 0
    clear_status;
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 4, A_CTRL, IE, 4'hF, OK);
    check(irq === 1'b1, "CTRL-WINS EN0 one-shot: EXPIRED");
    rd(A_COUNT, 32'h0, OK, "CTRL-WINS EN0 one-shot: COUNT 0");
    rd(A_CTRL, IE, OK, "CTRL-WINS EN0 one-shot: EN 0");
    // (c) periodic, EN 0
    clear_status;
    wr_nb(A_CTRL, EN | IE | MODE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 4, A_CTRL, IE | MODE, 4'hF, OK);
    check(irq === 1'b1, "CTRL-WINS EN0 periodic: EXPIRED");
    rd(A_COUNT, 32'd4, OK, "CTRL-WINS EN0 periodic: COUNT = LOAD");
    rd(A_CTRL, IE | MODE, OK, "CTRL-WINS EN0 periodic: EN 0");
    repeat (6) step;
    rd(A_COUNT, 32'd4, OK, "CTRL-WINS EN0 periodic: stopped");
    rd(A_STATUS, 32'h1, OK, "CTRL-WINS EN0 periodic: EXPIRED kept");
    // (d) periodic restart into one-shot (RESTART-MODE)
    clear_status;
    wr_nb(A_CTRL, EN | IE | MODE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 4, A_CTRL, EN | IE, 4'hF, OK);
    e1 = wr_edge;
    check(irq === 1'b1, "RESTART-MODE: EXPIRED on end edge");
    rd(A_COUNT, 32'd4, OK, "RESTART-MODE: COUNT = LOAD");
    wr_at(e1 + 3, A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b0, "RESTART-MODE: cleared");
    step;
    check(irq === 1'b1, "RESTART-MODE: ends after LOAD");
    rd(A_CTRL, IE, OK, "RESTART-MODE: one-shot stops");
    rd(A_COUNT, 32'h0, OK, "RESTART-MODE: COUNT 0");

    // T10: restart while running
    clear_status;
    wr(A_LOAD, 32'd10, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 3, A_CTRL, EN | IE, 4'hF, OK);
    e1 = wr_edge;
    rd(A_COUNT, 32'd10, OK, "restart: COUNT = LOAD");
    while (cyc < e1 + 10) begin
      check(irq === 1'b0, "restart: no end before E2+N");
      step;
    end
    check(irq === 1'b1, "restart: end at E2+N");
    rd(A_CTRL, IE, OK, "restart: one-shot ended");

    // T11: LOAD write does not change COUNT
    clear_status;
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 2, A_LOAD, 32'd50, 4'hF, OK);
    rd(A_COUNT, 32'd8, OK, "LOAD write keeps COUNT");
    while (cyc < e0 + 10) begin
      check(irq === 1'b0, "LOAD write: end timing kept");
      step;
    end
    check(irq === 1'b1, "LOAD write: end at E+10");
    rd(A_LOAD, 32'd50, OK, "LOAD readback");
    clear_status;
    wr_nb(A_CTRL, EN, 4'hF, OK);
    rd(A_COUNT, 32'd50, OK, "new LOAD used at next start");
    wr(A_CTRL, 32'h0, 4'hF, OK);

    // T12: running undisturbed
    clear_status;
    wr(A_LOAD, 32'd40, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    e0 = wr_edge;
    wr(A_COUNT, 32'h5, 4'hF, SLV);
    wr(32'h1, 32'hFFFF_FFFF, 4'hF, SLV);
    wr(A_STATUS, 32'h0, 4'hF, OK);
    wr(A_STATUS, 32'h2, 4'hF, OK);
    wr(A_STATUS, 32'h1, 4'b1110, OK);
    if (AW > 4) wr(32'h10, 32'hFFFF_FFFF, 4'hF, SLV);
    rd(A_CTRL, EN | IE, OK, "undisturbed: CTRL");
    rd(A_STATUS, 32'h0, OK, "undisturbed: STATUS");
    rd(A_COUNT, 32'd40 - (cyc - e0), OK, "undisturbed: COUNT");
    while (cyc < e0 + 40) begin
      check(irq === 1'b0, "undisturbed: no early end");
      step;
    end
    check(irq === 1'b1, "undisturbed: end at E+40");

    // T13: LOAD 0 and LOAD 1
    clear_status;
    wr(A_LOAD, 32'd0, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    check(irq === 1'b0, "LOAD0 one-shot: no end on E");
    step;
    check(irq === 1'b1, "LOAD0 one-shot: end on E+1");
    rd(A_CTRL, IE, OK, "LOAD0 one-shot: EN cleared");
    rd(A_COUNT, 32'h0, OK, "LOAD0 one-shot: COUNT 0");
    clear_status;
    wr_nb(A_CTRL, EN | IE | MODE, 4'hF, OK);
    check(irq === 1'b0, "LOAD0 periodic: no end on E");
    rd(A_COUNT, 32'h0, OK, "LOAD0 periodic: COUNT 0 after E");
    check(irq === 1'b1, "LOAD0 periodic: ended");
    wr(A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b1, "LOAD0 periodic: every edge is an end");
    rd(A_STATUS, 32'h1, OK, "LOAD0 periodic: clear never wins");
    rd(A_CTRL, EN | IE | MODE, OK, "LOAD0 periodic: EN stays");
    rd(A_COUNT, 32'h0, OK, "LOAD0 periodic: COUNT 0");
    wr(A_CTRL, IE | MODE, 4'hF, OK);
    rd(A_CTRL, IE | MODE, OK, "LOAD0 periodic: stopped");
    rd(A_COUNT, 32'h0, OK, "LOAD0 periodic: COUNT after stop");
    clear_status;
    rd(A_STATUS, 32'h0, OK, "LOAD0 periodic: clear after stop");
    wr(A_LOAD, 32'd1, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    check(irq === 1'b0, "LOAD1: no end on E");
    rd(A_COUNT, 32'd1, OK, "LOAD1: COUNT 1 after E");
    check(irq === 1'b1, "LOAD1: ended");
    rd(A_CTRL, IE, OK, "LOAD1: EN cleared");
    rd(A_COUNT, 32'h0, OK, "LOAD1: COUNT 0");
    clear_status;
    wr_nb(A_CTRL, EN | IE, 4'hF, OK);
    check(irq === 1'b0, "LOAD1 exact: before");
    step;
    check(irq === 1'b1, "LOAD1 exact: end on E+1");

    // T14: irq follows IE on its edge
    wr(A_CTRL, 32'h0, 4'hF, OK);
    clear_status;
    wr(A_LOAD, 32'd0, 4'hF, OK);
    wr_nb(A_CTRL, EN, 4'hF, OK);
    step; step;
    rd(A_STATUS, 32'h1, OK, "IE test: EXPIRED");
    check(irq === 1'b0, "IE 0: irq low");
    wr_nb(A_CTRL, IE, 4'hF, OK);
    check(irq === 1'b1, "IE write raises irq on its edge");
    step;
    wr_nb(A_CTRL, 32'h0, 4'hF, OK);
    check(irq === 1'b0, "IE 0 write drops irq on its edge");
    step;
    wr_nb(A_CTRL, IE, 4'hF, OK);
    check(irq === 1'b1, "IE 1 again");
    step;
    wr_nb(A_STATUS, 32'h1, 4'hF, OK);
    check(irq === 1'b0, "clear drops irq on its edge");
    step;

    // T15: 32-bit count
    wr(A_CTRL, 32'h0, 4'hF, OK);
    clear_status;
    wr(A_LOAD, 32'h8000_0001, 4'hF, OK);
    wr_nb(A_CTRL, EN, 4'hF, OK);
    rd(A_COUNT, 32'h8000_0001, OK, "32-bit: start value");
    rd(A_COUNT, 32'h7FFF_FFFF, OK, "32-bit: borrow through bit 31");
    rd(A_STATUS, 32'h0, OK, "32-bit: no false end");
    wr(A_CTRL, 32'h0, 4'hF, OK);
    wr(A_LOAD, 32'h0020_0002, 4'hF, OK);
    wr_nb(A_CTRL, EN, 4'hF, OK);
    step; step;
    rd(A_COUNT, 32'h0020_0000, OK, "32-bit: passes 0x00200001");
    rd(A_COUNT, 32'h001F_FFFE, OK, "32-bit: borrow through bit 21");
    rd(A_STATUS, 32'h0, OK, "32-bit: end tests all bits");
    wr(A_CTRL, 32'h0, 4'hF, OK);

    // T16: LOAD write on periodic end edge (either outcome accepted)
    clear_status;
    wr(A_LOAD, 32'd4, 4'hF, OK);
    wr_nb(A_CTRL, EN | MODE, 4'hF, OK);
    e0 = wr_edge;
    wr_at(e0 + 4, A_LOAD, 32'd6, 4'hF, OK);
    x = wr_edge;
    rd_raw(A_COUNT);
    v = rd_last;
    check(rd_last == 32'd4 || rd_last == 32'd6, "LOAD-END-EDGE: reload old or new");
    check_eq({30'd0, rresp_last}, {30'd0, OK}, "rresp");
    if (v != 4 && v != 6) v = 4;
    wait_until(x + v - 2);
    rd(A_COUNT, 32'd2, OK, "LOAD-END-EDGE: period length");
    rd(A_COUNT, 32'd6, OK, "LOAD-END-EDGE: next reload uses new LOAD");
    wr(A_CTRL, 32'h0, 4'hF, OK);

    // T17: reset
    clear_status;
    wr(A_LOAD, 32'd2, 4'hF, OK);
    wr_nb(A_CTRL, EN | IE | MODE, 4'hF, OK);
    repeat (4) step;
    check(irq === 1'b1, "pre-reset irq");
    rready = 1'b0;
    araddr = A_CTRL; arvalid = 1'b1;
    step; arvalid = 1'b0;
    check(rvalid === 1'b1, "pre-reset rvalid pending");
    awaddr = A_LOAD; awvalid = 1'b1; wvalid = 1'b0; bready = 1'b1;
    step; awvalid = 1'b0;
    check(awready === 1'b0 && bvalid === 1'b0, "pre-reset AW held");
    aresetn = 1'b0;
    step;
    aresetn = 1'b1;
    check(irq === 1'b0, "reset: irq 0");
    check(rvalid === 1'b0 && bvalid === 1'b0, "reset: no responses");
    check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "reset: READYs");
    rready = 1'b1;
    wdata = 32'hFF; wstrb = 4'hF; wvalid = 1'b1;
    step; wvalid = 1'b0;
    check(bvalid === 1'b0, "reset dropped held AW");
    check(wready === 1'b0, "W now held");
    awaddr = A_STATUS; awvalid = 1'b1;
    step; awvalid = 1'b0;
    check(bvalid === 1'b1, "write completes with new AW");
    check_eq({30'd0, bresp}, {30'd0, OK}, "post-reset bresp");
    step;
    rd(A_LOAD,   32'h0, OK, "reset: LOAD");
    rd(A_CTRL,   32'h0, OK, "reset: CTRL");
    rd(A_COUNT,  32'h0, OK, "reset: COUNT");
    rd(A_STATUS, 32'h0, OK, "reset: STATUS");
    repeat (3) step;
    rd(A_COUNT, 32'h0, OK, "reset: count stopped");
    check(irq === 1'b0, "reset: irq stays 0");

    bready = 1'b0;
    awaddr = A_LOAD; wdata = 32'h77; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
    step; awvalid = 1'b0; wvalid = 1'b0;
    check(bvalid === 1'b1, "pre-reset B pending");
    step;
    check(bvalid === 1'b1, "pre-reset B held");
    aresetn = 1'b0;
    step;
    aresetn = 1'b1;
    check(bvalid === 1'b0, "reset clears bvalid");
    check(awready === 1'b1 && wready === 1'b1, "reset: READYs after B");
    bready = 1'b1;
    rd(A_LOAD, 32'h0, OK, "reset: LOAD after B reset");

    wdata = 32'h99; wstrb = 4'hF; wvalid = 1'b1;
    step; wvalid = 1'b0;
    check(wready === 1'b0, "pre-reset W held");
    aresetn = 1'b0;
    step;
    aresetn = 1'b1;
    check(wready === 1'b1, "reset dropped held W");
    awaddr = A_LOAD; awvalid = 1'b1;
    step; awvalid = 1'b0;
    check(bvalid === 1'b0, "AW alone after reset does not complete");
    check(awready === 1'b0, "AW now held");
    wdata = 32'h1234; wstrb = 4'hF; wvalid = 1'b1;
    step; wvalid = 1'b0;
    check(bvalid === 1'b1, "completes with new W");
    step;
    rd(A_LOAD, 32'h1234, OK, "new W data written, old W dropped");

    $display("axil_timer_tb_core AW=%0d: %0d passed, %0d failed", AW, passed, failed);
    done = 1'b1;
  end
endmodule

module axil_timer_tb;
  axil_timer_tb_core #(.AW(4)) u_aw4 ();
  axil_timer_tb_core #(.AW(5)) u_aw5 ();
  axil_timer_tb_core #(.AW(8)) u_aw8 ();

  reg [8*64-1:0] nonce;
  integer passed;
  integer failed;

  initial begin
    nonce = 0;
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
    wait (u_aw4.done === 1'b1 && u_aw5.done === 1'b1 && u_aw8.done === 1'b1);
    passed = u_aw4.passed + u_aw5.passed + u_aw8.passed;
    failed = u_aw4.failed + u_aw5.failed + u_aw8.failed;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  initial begin
    #2000000;
    $error("timeout: testbench did not complete");
    passed = u_aw4.passed + u_aw5.passed + u_aw8.passed;
    failed = u_aw4.failed + u_aw5.failed + u_aw8.failed + 1;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule
